type State interface{ Handle(c *Conn, e Event) }

type Closed struct{}

func (Closed) Handle(c *Conn, e Event) {
    if e == Open {
        c.state = Listening{}   // transition: replace the state value
    }
}

type Conn struct{ state State }

func (c *Conn) On(e Event) { c.state.Handle(c, e) }

